namespace KPMG.Pulse.Back.Accounting.Mandate.Sql.Implementation
{
    using System;
    using System.Linq.Expressions;
    using Microsoft.EntityFrameworkCore;
    using Microsoft.Extensions.Options;
    using Microsoft.Identity.Client;

    public class SqlMandateRepository : IMandateRepository
    {
        private readonly IOptions<SqlMandateRepositoryOptions> options;

        public SqlMandateRepository(IOptions<SqlMandateRepositoryOptions> options)
        {
            if (options is null)
            {
                throw new ArgumentNullException(nameof(options));
            }

            options.Value.Validate();
            this.options = options;
        }

        public async Task<CompanyDb> GetCompanyBySiretAsync(string siret)
        {
            using var context = new MandateContext(this.options);

            var company = context.Company
                    .Include(c => c.Personal)
                    .Include(c => c.JeDeclareFolder)
                    .Where(_ => _.SiretNumber == siret && _.IsActive);

            if (!await company.AnyAsync())
            {
                throw CompanyNotFoundException.FromSiret(siret);
            }

            if (await company.CountAsync() > 1)
            {
                throw new InvalidOperationException($"there is more then one company with siret {siret}");
            }

            return await company.SingleAsync()!;
        }

        public async Task<(List<CollectionDb>, int)> SearchCollectionsAsync(CollectionQuery query)
        {
            using var context = new MandateContext(this.options);
            var mandates = context.Collection
                .Include(c => c.Bank)
                .Include(c => c.JeDeclareCollection)
                .Include(item => item.Company).ThenInclude(c => c!.JeDeclareFolder)
                .Include(item => item.Statuses).ThenInclude(item => item.RefStatusCode)
                .AsQueryable();

            if (query?.CollaboratorId != 0)
            {
                mandates = ApplayCollaboratorFilter(mandates, query!.CollaboratorId, context);
            }

            mandates = ApplySearchTermFilter(mandates, query!);
            mandates = ApplyStatusCodesFilter(mandates, query);
            mandates = ApplyCreationDateFilter(mandates, query);
            mandates = ApplyModificationDateFilter(mandates, query);
            mandates = ApplySorting(mandates, query);

            var list = await PaginatedListAsync(mandates, query).ConfigureAwait(false);
            var count = await mandates.CountAsync();

            return (list, count);
        }

        public async Task<List<CompanyDb?>> GetAllCompaniesByCollaboratorAsync(string email)
        {
            using var context = new MandateContext(this.options);
            var companiesForCollaborator = context.Collaborator
                .AsNoTracking()
                .Include(c => c.CompanyCollaborators)
                .ThenInclude(cc => cc.Company)
                .Where(c => c.Email == email)
                .SelectMany(c => c.CompanyCollaborators)
                .Select(cc => cc.Company);

            return await companiesForCollaborator.Where(_ => _.IsActive).ToListAsync().ConfigureAwait(false);
        }

        public async Task<RefBankDb> GetRefBankByCodeAsync(string bankCode)
        {
            using var context = new MandateContext(this.options);
            var banks = context.RefBank.AsNoTracking().Where(r => r.BankCode == bankCode);
            if (!await banks.AnyAsync().ConfigureAwait(false))
            {
                throw BankCodeNotFoundException.FromId(bankCode);
            }
            else
            {
                return await banks.SingleAsync().ConfigureAwait(false);
            }
        }

        public async Task<StatusDb> GetRefStatusCodeByJdcCodeAsync(string jdcStatusCode)
        {
            int statusCode = ValidateAndParseStatusCode(jdcStatusCode);

            using var context = new MandateContext(this.options);
            var query = context.RefStatusCode
                .Where(item => item.StatusCode == statusCode);
            var status = await query.FirstOrDefaultAsync().ConfigureAwait(false) ?? throw StatusNotFoundException.FromId(jdcStatusCode);

            // At this point, status is guaranteed to be not null and is the matched entity
            return new StatusDb()
            {
                StatusCode = statusCode,
                RefStatusCode = status!,
            };
        }

        public async Task<byte[]> GetPdfTemplateByCodeAsync(string bankCode)
        {
            using var context = new MandateContext(this.options);
            var template = context.RefPdfTemplate.AsNoTracking().Where(r => r.BankCode == bankCode);
            if (!await template.AnyAsync().ConfigureAwait(false))
            {
                throw BankCodeNotFoundException.FromId(bankCode);
            }
            else
            {
                var refPdfTemplate = await template.SingleAsync().ConfigureAwait(false);
                return refPdfTemplate.PdfFile;
            }
        }

        public async Task<CollectionDb> GetCollectionById(Guid id)
        {
            using var context = new MandateContext(this.options);

            var collectionDb = context.Collection
                .Include(c => c.Bank)
                .Include(c => c.JeDeclareCollection)
                .Include(item => item!.Personal)
                .Include(item => item.Company).ThenInclude(item => item!.JeDeclareFolder)
                .Include(item => item.Statuses).ThenInclude(item => item.RefStatusCode)
                .AsNoTracking().Where(c => c.Id == id);

            if (!await collectionDb.AnyAsync().ConfigureAwait(false))
            {
                throw CollectionNotFoundException.FromId(id.ToString());
            }

            return await collectionDb.SingleAsync().ConfigureAwait(false);
        }

        public async Task SaveSignatoryAsync(PersonalDb personalDb)
        {
            using var context = new MandateContext(this.options);

            await context.AddAsync(personalDb);
            await context.SaveChangesAsync();
        }

