        public async Task DeleteFakeRefAsync()
        {
            await this.DeleteFakeDataAsync();
            using var context = new MandateContext(this.options);
            context.RemoveRange(await context.RefStatusCode.ToListAsync());
            context.RemoveRange(await context.RefBank.Where(b => b.BankCode.StartsWith("9999")).ToListAsync());
            context.RemoveRange(await context.RefPdfTemplate.Where(b => b.BankCode == "99999").ToListAsync());
            await context.SaveChangesAsync();
        }

        public async Task CreateFakeAuthAsync()
        {
            var rand = new Random();
            using var context = new MandateContext(this.options);
            string[] collabs = new string[] { "ccouchut", "cdewet", "melleuch", "mharchaoui", "fmanadi", "cmarwa", "smedini", "gnguepi", "clementprati" };
            foreach (var collab in collabs)
            {
                if (!context.Collaborator.Any(t => t.Email == collab + "@kpmg.fr"))
                {
                    await context.Collaborator.AddAsync(new CollaboratorDb()
                    {
                        Id = rand.Next(),
                        Email = collab + "@kpmg.fr",
                        FirstName = "FAKE",
                        LastName = collab,
                        IsActive = true,
                    });
                    await context.SaveChangesAsync();
                }
            }

            var ourIds = context.Collaborator.Where(c => collabs.Select(s => s + "@kpmg.fr").ToList().Contains(c.Email)).Select(c => c.Id);
            context.RemoveRange(await context.CompanyCollaborator.Where(cc => ourIds.Contains(cc.CollaboratorId)).ToListAsync());
            await context.SaveChangesAsync();

            var allCompanies = context.Company.Select(c => c.Id);
            foreach (var companyId in allCompanies)
            {
                foreach (var ourId in ourIds)
                {
                    await context.CompanyCollaborator.AddAsync(new CompanyCollaboratorDb()
                    {
                        CompanyId = companyId,
                        CollaboratorId = ourId,
                    });
                }
            }

            await context.SaveChangesAsync();
        }

        public async Task DeleteFakeAuthAsync()
        {
            using var context = new MandateContext(this.options);
            string[] collabs = new string[] { "ccouchut", "cdewet", "melleuch", "mharchaoui", "fmanadi", "cmarwa", "smedini", "gnguepi", "clementprati" };
            var ourIds = context.Collaborator.Where(c => collabs.Select(s => s + "@kpmg.fr").ToList().Contains(c.Email)).Select(c => c.Id);
            context.RemoveRange(await context.CompanyCollaborator.Where(cc => ourIds.Contains(cc.CollaboratorId)).ToListAsync());
            context.RemoveRange(await context.Collaborator.Where(c => ourIds.Contains(c.Id)).ToListAsync());
            await context.SaveChangesAsync();
        }

