        public async Task DeleteFakeDataAsync()
        {
            using var context = new MandateContext(this.options);
            var fakeCompanyIds = context.Company.Where(c => c.ErpId != null && c.ErpId.StartsWith("200000")).Select(c => c.Id);
            var fakeCollectionIds = context.Collection.Where(c => fakeCompanyIds.Contains(c.CompanyId)).Select(c => c.Id);

            context.RemoveRange(await context.Status.Where(s => fakeCollectionIds.Contains(s.CollectionId)).ToListAsync());
            context.RemoveRange(await context.JeDeclareCollection.Where(s => fakeCollectionIds.Contains(s.CollectionId)).ToListAsync());
            context.RemoveRange(await context.Personal.Where(s => s.CollectionId.HasValue && fakeCollectionIds.Contains(s.CollectionId!.Value)).ToListAsync());
            context.RemoveRange(await context.Collection.Where(s => fakeCollectionIds.Contains(s.Id)).ToListAsync());
            context.RemoveRange(await context.JeDeclareFolder.Where(s => fakeCompanyIds.Contains(s.CompanyId)).ToListAsync());
            context.RemoveRange(await context.Personal.Where(s => s.CompanyId.HasValue && fakeCompanyIds.Contains(s.CompanyId!.Value)).ToListAsync());
            context.RemoveRange(await context.CompanyCollaborator.Where(cc => fakeCompanyIds.Contains(cc.CompanyId)).ToListAsync());
            context.RemoveRange(await context.Company.Where(s => fakeCompanyIds.Contains(s.Id)).ToListAsync());
            await context.SaveChangesAsync();
        }

        public async Task<CompanyDb> GetCompanyByErpIdAsync(string erpId)
        {
            using var context = new MandateContext(this.options);
            var company = context.Company
                .Include(c => c.Personal)
                .Include(c => c.JeDeclareFolder)
                .AsNoTracking().Where(c => c.ErpId == erpId && c.IsActive);
            if (!await company.AnyAsync().ConfigureAwait(false))
            {
                throw CompanyNotFoundException.FromId(erpId);
            }

            return await company.SingleAsync().ConfigureAwait(false);
        }

        public async Task<CollaboratorDb> GetCollaboratorByEmailAsync(string collaboratorEmail)
        {
            using var context = new MandateContext(this.options);

            var collab = context.Collaborator.AsNoTracking()
                .Where(c => c.Email.ToLower() == collaboratorEmail.ToLower() && c.IsActive);

            return await collab.SingleAsync();
        }

        public async Task CreateOrUpdateFolderAsync(string bankServicesProviderId, int companyId)
        {
            using var context = new MandateContext(this.options);

            var folder = await context.JeDeclareFolder
                .Where(item => item.CompanyId == companyId)
                .SingleOrDefaultAsync().ConfigureAwait(false);

            if (folder == null)
            {
                JeDeclareFolderDb jeDeclareFolder = new JeDeclareFolderDb
                {
                    CompanyId = companyId,
                    JdcDossierId = bankServicesProviderId,
                };
                await context.JeDeclareFolder.AddAsync(jeDeclareFolder);
            }
            else
            {
                JeDeclareFolderDb jeDeclareFolder = new JeDeclareFolderDb
                {
                    Id = folder.Id,
                    CompanyId = companyId,
                    JdcDossierId = bankServicesProviderId,
                };

                context.Entry(folder).CurrentValues.SetValues(jeDeclareFolder);
            }

            await context.SaveChangesAsync();
        }

