        public async Task<StatusDb> CreateStatusAsync(Guid collectionId, StatusDb statusDb)
        {
            using var context = new MandateContext(this.options);

            await context.Status.AddAsync(statusDb);
            await context.SaveChangesAsync();

            return await context.Status
                .Include(item => item.RefStatusCode)
                .Where(item => item.CollectionId == collectionId &&
                    item.StatusCode == statusDb.StatusCode &&
                    item.StatusDate == statusDb.StatusDate)
                .SingleAsync()
                .ConfigureAwait(false);
        }

        public async Task UpdateCurrentStatusAsync(Guid collectionId)
        {
            using var context = new MandateContext(this.options);
            var statusDb = await context.Status.SingleOrDefaultAsync(item => item.CollectionId == collectionId && item.IsCurrent);

            if (statusDb == null)
            {
                throw StatusNotFoundException.FromId(collectionId);
            }

            StatusDb toUpdate = new StatusDb
            {
                Id = statusDb.Id,
                StatusCode = statusDb.StatusCode,
                CollectionId = statusDb.CollectionId,
                CollectionStatusCode = statusDb.CollectionStatusCode,
                CreatedBy = statusDb.CreatedBy,
                IsCurrent = false,
                MandateFile = statusDb.MandateFile,
                StatusDate = statusDb.StatusDate,
            };

            context.Entry(statusDb).CurrentValues.SetValues(toUpdate);
            await context.SaveChangesAsync();
        }

        public async Task<CompanyDb> GetCompanyByErpIdSiretAsync(string erpId, string siretNumber)
        {
            using var context = new MandateContext(this.options);

            if (await context.Company.AnyAsync(i => i.ErpId == erpId))
            {
                var companiesByErpId = await context.Company
                    .Where(i => i.ErpId == erpId && i.SiretNumber == siretNumber && i.IsActive)
                    .OrderBy(item => item.SiretNumber)
                    .ToListAsync();

                if (companiesByErpId.Count > 1)
                {
                    throw new CustomCompanyNotFoundException(ExceptionType.AccountNumberMatchDoubleSiret);
                }
                else if (companiesByErpId.Count == 0)
                {
                    throw new CustomCompanyNotFoundException(ExceptionType.AccountNumberNoMatchSiret);
                }
                else
                {
                    return companiesByErpId.Single();
                }
            }
            else if (await context.Company.AnyAsync(i => i.SiretNumber == siretNumber))
            {
                if (await context.Company.CountAsync(i => i.SiretNumber == siretNumber) > 1)
                {
                    throw new CustomCompanyNotFoundException(ExceptionType.NoAccountNumberMatchDoubleSiret);
                }

                return await context.Company.SingleAsync(item => item.SiretNumber == siretNumber && item.IsActive);
            }
            else
            {
                throw new CustomCompanyNotFoundException(ExceptionType.NoAccountNumberNoMatchSiret);
            }
        }

